css:
.d-table-reconcile-keys{width:100%;max-width:430px;min-width:0;color:var(--ink);font:inherit;font-size:14px;line-height:1.5;overflow-wrap:anywhere}
.d-table-reconcile-keys *,.d-table-reconcile-keys *::before,.d-table-reconcile-keys *::after{box-sizing:border-box}
.d-table-reconcile-keys [hidden]{display:none!important}
.d-table-reconcile-keys .d-row{display:flex;flex-wrap:wrap;align-items:center;gap:8px;margin:8px 0}
.d-table-reconcile-keys .d-note{display:block;margin:8px 0 0;color:var(--muted);font-size:12px;min-height:1.5em}
.d-table-reconcile-keys label{display:block;margin:8px 0}
.d-table-reconcile-keys input,.d-table-reconcile-keys select,.d-table-reconcile-keys textarea,.d-table-reconcile-keys button{font:inherit;color:inherit;max-width:100%;min-width:0}
.d-table-reconcile-keys input:not([type=checkbox]):not([type=radio]),.d-table-reconcile-keys select,.d-table-reconcile-keys textarea{width:100%;padding:8px;border:1px solid var(--line);border-radius:var(--radius-control);background:var(--paper)}
.d-table-reconcile-keys button{padding:6px 10px;border:1px solid var(--line);border-radius:var(--radius-control);background:var(--paper);cursor:pointer}
.d-table-reconcile-keys button:disabled{opacity:.5;cursor:default}
.d-table-reconcile-keys :focus-visible{outline:2px solid var(--ink);outline-offset:3px}
.d-table-reconcile-keys [aria-invalid=true]{border-color:var(--warn)!important}
.d-table-reconcile-keys .d-scroll{max-width:100%;overflow:auto}
.d-table-reconcile-keys table{width:100%;border-collapse:collapse;font-size:12px;text-align:left}
.d-table-reconcile-keys th,.d-table-reconcile-keys td{padding:7px;border-bottom:1px solid var(--line);vertical-align:top}
.d-table-reconcile-keys caption{text-align:left;font-weight:600;margin-bottom:8px}
.d-table-reconcile-keys progress{width:100%;accent-color:var(--ink)}
.d-table-reconcile-keys pre{white-space:pre-wrap;overflow-wrap:anywhere;font-size:12px}
.d-table-reconcile-keys h3,.d-table-reconcile-keys p{margin:8px 0}
.d-table-reconcile-keys [aria-pressed=true],.d-table-reconcile-keys [aria-selected=true]{border-color:var(--ink);font-weight:650}
.d-table-reconcile-keys .d-grow{flex:1;min-width:100px}
.d-table-reconcile-keys summary{cursor:pointer;padding:6px 0}
.d-table-reconcile-keys ul,.d-table-reconcile-keys ol{padding-left:24px}

init:
root => {
 const q = selector => root.querySelector(selector);
 const qa = selector => [...root.querySelectorAll(selector)];
 const say = text => { const out = q('[data-out]'); if (out) out.textContent = text; };
 ((root,q,qa,say)=>{q('[data-compare]').onclick=()=>{const read=selector=>new Set(q(selector).value.split(/\r?\n/).map(s=>s.trim()).filter(Boolean)),left=read('[data-left]'),right=read('[data-right]');q('[data-result]').replaceChildren();[['共同项',[...left].filter(id=>right.has(id))],['仅计划中',[...left].filter(id=>!right.has(id))],['仅交付中',[...right].filter(id=>!left.has(id))]].forEach(([label,ids])=>{const p=document.createElement('p');p.textContent=label+'：'+(ids.join('、')||'无');q('[data-result]').append(p);});say('已按唯一编号完成本地核对');};})(root, q, qa, say);
}
